/// Blanket authoring extensions on any [`View`].
pub trait ViewExt: View + Sized {
    /// Apply one or more modifiers (innermost-first). The list is a single
    /// modifier or a tuple: `.modifiers(Padding(16.0))`,
    /// `.modifiers((Padding(16.0), FontSize(12.0)))`.
    fn modifiers<L: ModifierList>(self, modifiers: L) -> Modified<Self> {
        Modified {
            view: self,
            mods: modifiers.into_modifiers(),
        }
    }

    /// Scope a [`ButtonStyle`] down this subtree (the active style for any
    /// `Button` whose own content it supplies).
    fn button_style(self, style: impl ButtonStyle + 'static) -> WithButtonStyle<Self> {
        WithButtonStyle {
            view: self,
            style: Rc::new(style),
        }
    }

    /// Scope a [`VideoStyle`] down this subtree (the active style for any
    /// `Video` surface whose control content it supplies).
    fn video_style(self, style: impl VideoStyle + 'static) -> WithVideoStyle<Self> {
        WithVideoStyle {
            view: self,
            style: Rc::new(style),
        }
    }
}

impl<T: View> ViewExt for T {}

// ---------------------------------------------------------------------------
// Environment + styles
// ---------------------------------------------------------------------------

/// The subtree-scoped environment — the one inheritance mechanism.
///
/// Java implements this scope with a thread-local over the synchronous render
/// pass; `no_std` Rust threads it explicitly through [`View::build_env`]. A
/// style-setting wrapper saves/restores the slot around building its subtree.
#[derive(Default)]
pub struct Environment {
    button_style: Option<Rc<dyn ButtonStyle>>,
    video_style: Option<Rc<dyn VideoStyle>>,
}

impl Environment {
    /// An empty environment.
    pub fn new() -> Self {
        Self::default()
    }

    /// The active button style (defaults to [`PlainButtonStyle`]).
    pub fn button_style(&self) -> Rc<dyn ButtonStyle> {
        self.button_style
            .clone()
            .unwrap_or_else(|| Rc::new(PlainButtonStyle))
    }

    /// The active video style (defaults to [`NativeVideoStyle`]).
    pub fn video_style(&self) -> Rc<dyn VideoStyle> {
        self.video_style
            .clone()
            .unwrap_or_else(|| Rc::new(NativeVideoStyle))
    }
}

/// A button style: supplies a button's **content** (the control owns the native
/// component and the interaction). `None` = the control's native content.
pub trait ButtonStyle {
    /// Build the styled content for `config`, or `None` for the native path.
    fn make_body(&self, config: &ButtonConfig) -> Option<Box<dyn View>>;
}

/// The default style: the button's own label (native path, no content view).
pub struct PlainButtonStyle;

impl ButtonStyle for PlainButtonStyle {
    fn make_body(&self, _config: &ButtonConfig) -> Option<Box<dyn View>> {
        None
    }
}

/// A bordered button style: the label with padding + a border.
pub struct BorderedButtonStyle;

impl ButtonStyle for BorderedButtonStyle {
    fn make_body(&self, config: &ButtonConfig) -> Option<Box<dyn View>> {
        let label = Text::with(|t| {
            t.text(config.label.clone());
        })
        .modifiers((
            Padding(8.0),
            Border::new(Color::argb(0xFF_888888), 1.0),
        ));
        Some(Box::new(label))
    }
}

/// A video style: supplies a [`Video`] surface's **content** — the transport
/// control UI shown over/next to the playback (spec DSL.md §5.7). The control
/// owns the native component and the media binding; a style only supplies
/// content and never installs a binding. `None` = the renderer's native controls.
pub trait VideoStyle {
    /// Build the styled content for `config`, or `None` for the native path.
    fn make_body(&self, config: &VideoStyleConfig) -> Option<Box<dyn View>>;
}

/// What a [`VideoStyle`] reads (spec DSL.md §5.7): the surface's controller, so
/// the style's own controls can drive the same playback.
pub struct VideoStyleConfig {
    controller: Option<Rc<MediaController>>,
}

impl VideoStyleConfig {
    /// The controller this surface renders (`None` for an unbound surface).
    pub fn controller(&self) -> Option<&Rc<MediaController>> {
        self.controller.as_ref()
    }
}

/// The default style: renderer-native controls (no content view, so the surface
/// stays a leaf in Native Token Mode).
pub struct NativeVideoStyle;

impl VideoStyle for NativeVideoStyle {
    fn make_body(&self, _config: &VideoStyleConfig) -> Option<Box<dyn View>> {
        None
    }
}

/// A view wrapped by a scoped [`VideoStyle`] (applied via
/// [`ViewExt::video_style`]).
pub struct WithVideoStyle<V> {
    view: V,
    style: Rc<dyn VideoStyle>,
}

impl<V: View> View for WithVideoStyle<V> {
    fn build_env(&self, env: &mut Environment) -> Node {
        let previous = env.video_style.take();
        env.video_style = Some(self.style.clone());
        let node = self.view.build_env(env);
        env.video_style = previous;
        node
    }
}

impl<V: Configurable> Configurable for WithVideoStyle<V> {
    type Config = V::Config;
    fn config(&self) -> &Self::Config {
        self.view.config()
    }
    fn config_mut(&mut self) -> &mut Self::Config {
        self.view.config_mut()
    }
}

/// A view wrapped by a scoped [`ButtonStyle`] (applied via
/// [`ViewExt::button_style`]).
pub struct WithButtonStyle<V> {
    view: V,
    style: Rc<dyn ButtonStyle>,
}

impl<V: View> View for WithButtonStyle<V> {
    fn build_env(&self, env: &mut Environment) -> Node {
        let previous = env.button_style.take();
        env.button_style = Some(self.style.clone());
        let node = self.view.build_env(env);
        env.button_style = previous;
        node
    }
}

impl<V: Configurable> Configurable for WithButtonStyle<V> {
    type Config = V::Config;
    fn config(&self) -> &Self::Config {
        self.view.config()
    }
    fn config_mut(&mut self) -> &mut Self::Config {
        self.view.config_mut()
    }
}

/// A view wrapped by a list of modifiers (applied innermost-first at `build`).
pub struct Modified<V> {
    view: V,
    mods: Vec<Box<dyn ViewModifier>>,
}

impl<V: View> View for Modified<V> {
    fn build_env(&self, _env: &mut Environment) -> Node {
        let mut node = self.view.build_env(_env);
        for modifier in &self.mods {
            modifier.apply(&mut node);
        }
        node

package dev.pathland.view.core

/**
 * The presentation strategy for a `BUTTON`.
 *
 * A style receives the button's label content through [Configuration] and
 * returns the body to render. The DSL resolves the nearest `ButtonStyle` from
 * the `BUTTON_STYLE` environment key; the renderer still owns pressed/hover and
 * disabled chrome (interaction styling is not part of the protocol).
 */
interface ButtonStyle : Style {
    fun makeBody(config: Configuration): View?

    override fun body(content: View): View =
        EnvironmentView.of(content, Environment.BUTTON_STYLE, this)

    /** The button content handed to a style: the explicit label subtree, if any. */
    data class Configuration(val label: View?) {
        fun label(): View? = label
    }
}

package dev.pathland.view.dsl

import dev.pathland.view.core.ButtonStyle
import dev.pathland.view.core.Color
import dev.pathland.view.core.EmptyContent
import dev.pathland.view.core.LabelStyle
import dev.pathland.view.core.PathlandDsl
import dev.pathland.view.core.VideoStyle
import dev.pathland.view.core.View

/**
 * The default `ButtonStyle`: renders the label content unchanged.
 *
 * The renderer supplies the native button element and its platform chrome, so
 * this style intentionally adds no visual decoration.
 */
object PlainButtonStyle : ButtonStyle {
    override fun makeBody(config: ButtonStyle.Configuration): View? = config.label()
}

/**
 * A `ButtonStyle` that paints a rounded, bordered, tinted box around the label.
 *
 * Configure padding, background, border color, and radius through
 * [Config]/`borderedButtonStyle`. Label text is forced to white; the renderer
 * still owns focus/pressed states.
 */
class BorderedButtonStyle private constructor(private val config: Config) : ButtonStyle {

    /** Bordered button appearance: padding, background, border color, and radius. */
    @PathlandDsl
    class Config {
        /** Inner padding in logical points (default 10). */
        var padding: Float = 10f
        /** Box background (default blue). */
        var background: Color = Color.rgb(33, 150, 243)
        /** Border color (default darker blue). */
        var borderColor: Color = Color.rgb(25, 118, 210)
        /** Corner radius in logical points (default 6). */
        var radius: Float = 6f

        fun padding(value: Float): Config {
            padding = value
            return this
        }

        fun background(value: Color): Config {
            background = value
            return this
        }

        fun borderColor(value: Color): Config {
            borderColor = value
            return this
        }

        fun radius(value: Float): Config {
            radius = value
            return this
        }
    }

    override fun makeBody(config: ButtonStyle.Configuration): View? {
        val label = config.label() ?: return null
        return label
            .foregroundStyle(Color.WHITE)
            .padding(this.config.padding)
            .background(this.config.background)
            .border(this.config.borderColor, 1f, this.config.radius)
    }

    companion object {
        fun make(configure: Config.() -> Unit): BorderedButtonStyle {
            val config = Config()
            config.configure()
            return BorderedButtonStyle(config)
        }
    }
}

/** The default bordered style value. */
fun borderedButtonStyle(configure: BorderedButtonStyle.Config.() -> Unit = {}): BorderedButtonStyle =
    BorderedButtonStyle.make(configure)

/** The default button style value. */
fun plainButtonStyle(): ButtonStyle = PlainButtonStyle

/**
 * The default `LabelStyle`: icon then title in a small horizontal row.
 *
 * Missing parts are omitted; the result is a grouped subtree so the label keeps
 * a stable component type even when one part is absent.
 */
object DefaultLabelStyle : LabelStyle {
    override fun makeBody(config: LabelStyle.Configuration): View {
        val parts = buildList {
            config.icon()?.let { add(it) }
            config.title()?.let { add(it) }
        }
        return groupView(parts)
    }
}

/** A `LabelStyle` that renders only the title, dropping the icon. */
object TitleOnlyLabelStyle : LabelStyle {
    override fun makeBody(config: LabelStyle.Configuration): View =
        config.title() ?: groupView(emptyList())
}

/** A `LabelStyle` that renders only the icon, dropping the title. */
object IconOnlyLabelStyle : LabelStyle {
    override fun makeBody(config: LabelStyle.Configuration): View =
        config.icon() ?: groupView(emptyList())
}

/**
 * A `VideoStyle` that renders no content, leaving playback controls to the
 * renderer's native chrome. It returns the [EmptyContent] sentinel rather than
 * `null` so the slot still has a stable component type.
 */
object NativeVideoStyle : VideoStyle {
    override fun makeBody(config: VideoStyle.Configuration): View = EmptyContent.INSTANCE
}

