 //! Host-side reader: opcode frames -> native-element description.
 //!
 //! Consumes frames and builds a **native-element description**: the tree
 //! structure (`TREE`) plus constraint properties (`PARAMETER`) a renderer maps onto
 //! that platform's native elements (GTK widgets, DOM elements, HTML).
 //!
 //! The engine does not compute layout; this stores only what the renderer needs
 //! to create native elements and let them lay themselves out.

 use std::collections::BTreeMap;
 use std::collections::HashMap;

 use pathland_core::tokens::{resolve_ref as resolve_token_ref, Scheme, TokenTables, TokenValue};
 use pathland_core::{
     category, color_scheme_mode, component_type, meta, parameter, tree, value_type, AttributedString,
     Frame, Opcode, WindowMeta,
 };

 /// A decoded node in the host's native-element description.
 #[derive(Debug, Clone, PartialEq)]
 pub struct HostNode {
     pub id: u32,
     pub component_type: u16,
     /// The node's plain text (also the fallback for rich text).
     pub text: Option<String>,
     /// Decoded `PARAMETER::SET_ATTRIBUTED_TEXT` payload, if any.
     pub attributed: Option<AttributedString>,
     pub parent: Option<u32>,
     pub children: Vec<u32>,
     /// Constraint properties (propertyId -> value) for native layout/styling.
     pub properties: HashMap<u16, u32>,
     /// `STRING`-valued properties resolved at apply time (propertyId -> text).
     ///
     /// The wire carries strings in the arena / batch string section referenced
     /// by an offset; this map holds the resolved text for `LABEL`, `PROMPT`,
     /// `IMAGE_SOURCE`, `FONT_FAMILY`, … (see `spec/OPCODE.md`).
     pub strings: HashMap<u16, String>,
     /// `DESIGN_TOKEN`-typed properties (propertyId → token path, spec/TOKENS.md).
     ///
     /// The renderer resolves these against the theme and the active color
     /// scheme at apply time, materializing the concrete value into
     /// [`Self::properties`] / [`Self::strings`] (see
     /// [`RenderTree::resolve_tokens`]); the path is kept so it can be
     /// re-resolved when the scheme changes.
     pub token_refs: BTreeMap<u16, String>,
     /// `LIST`-typed properties decoded from the arena (propertyId → f32 values).
     ///
     /// Today the only list is a `VIEW_THAT_FITS` slot's `FIT_QUERY` threshold
     /// table (ascending `f32`s, spec/PRIMITIVES.md). The renderer measures its
     /// allocated width and derives the fit index.
     pub lists: HashMap<u16, Vec<f32>>,
     /// A `DATE_PICKER`'s last `PARAMETER::SET_DATE` value: (days since the Unix
     /// epoch, millis of day).
     pub date: Option<(i32, u32)>,
 }

 impl HostNode {
     /// A `STRING`-valued property resolved from the frame's string section.
     pub fn string_property(&self, prop: u16) -> Option<&str> {
         self.strings.get(&prop).map(String::as_str)
     }

     /// An `F32` property value, or a default when absent.
     pub fn f32_property(&self, prop: u16, default: f32) -> f32 {
         self.properties
             .get(&prop)
             .copied()
             .map(f32::from_bits)
             .unwrap_or(default)
     }

     /// A raw `U32` property value (no f32 reinterpretation), or a default.
     pub fn u32_property(&self, prop: u16, default: u32) -> u32 {
         self.properties.get(&prop).copied().unwrap_or(default)
     }

     /// The `SELECTED` checked state (U8 0/1).
     pub fn checked(&self) -> bool {
         self.u32_property(pathland_core::property_id::SELECTED, 0) != 0
     }

     /// A decoded `LIST` property (today a `FIT_QUERY` threshold table).
     pub fn list_property(&self, prop: u16) -> Option<&[f32]> {
         self.lists.get(&prop).map(Vec::as_slice)
     }
 }

 impl Default for HostNode {
     fn default() -> Self {
         Self {
             id: 0,
             component_type: component_type::HSTACK,
             text: None,
             attributed: None,
             parent: None,
             children: Vec::new(),
             properties: HashMap::new(),
             strings: HashMap::new(),
             token_refs: BTreeMap::new(),
             lists: HashMap::new(),
             date: None,
         }
     }
 }

 /// The host's native-element description of a rendered tree.
 #[derive(Debug)]
 pub struct RenderTree {
     /// nodeId -> node.
     pub nodes: HashMap<u32, HostNode>,
     /// Design-token overrides (`PARAMETER::SET_DESIGN_TOKEN`), base (light) values
     /// keyed by full path.
     overrides: BTreeMap<String, TokenValue>,
     /// `dark.*` overrides keyed by the bare path (the prefix stripped).
     dark_overrides: BTreeMap<String, TokenValue>,
     /// Renderer default token values (Tier 1 light + dark, spec/TOKENS.md) —
     /// concrete platform-appropriate fallbacks. A renderer may enrich these
     /// with native theme colors (e.g. GTK `@theme_*` named colors) via
     /// [`RenderTree::set_defaults`].
     defaults: BTreeMap<String, TokenValue>,
     dark_defaults: BTreeMap<String, TokenValue>,
     /// The platform-derived color scheme (OS/browser light-dark signal).
     /// Never carried by the protocol.
     platform_scheme: Scheme,
     /// An application override from `META::SET_COLOR_SCHEME`; `None` follows
     /// the platform.
     scheme_override: Option<Scheme>,
     /// Window/surface presentation metadata (`META::SET_WINDOW_METADATA`): the
     /// shared decode for every non-web renderer. Renderers map the fields onto
     /// their own window chrome.
     window: WindowMeta,
 }

 impl Default for RenderTree {
     fn default() -> Self {
         let (defaults, dark_defaults) = concrete_default_tables();
         Self {
             nodes: HashMap::new(),
             overrides: BTreeMap::new(),
             dark_overrides: BTreeMap::new(),
             defaults,
             dark_defaults,
             platform_scheme: Scheme::Light,
             scheme_override: None,
             window: WindowMeta::new(),
         }
     }
 }

 impl RenderTree {
     /// Install renderer default token tables (see [`RenderTree::defaults`]).
     pub fn set_defaults(
         &mut self,
         defaults: BTreeMap<String, TokenValue>,
         dark_defaults: BTreeMap<String, TokenValue>,
     ) {
         self.defaults = defaults;
         self.dark_defaults = dark_defaults;
         self.resolve_tokens();
     }

     /// The effective color scheme: the application override when set, else the
     /// platform-derived scheme.
     pub fn scheme(&self) -> Scheme {
         self.scheme_override.unwrap_or(self.platform_scheme)
     }

     /// Set the platform-derived (OS/browser) color scheme and re-resolve every
     /// token-referencing property. Ignored as an effective scheme while an
     /// application override is active; the stored platform value is used again
     /// once `set_scheme_override(None)` restores platform mode.
     pub fn set_scheme(&mut self, scheme: Scheme) {
         self.platform_scheme = scheme;
         self.resolve_tokens();
     }

     /// Force (`Some`) or release (`None` = platform) the effective color
     /// scheme (`META::SET_COLOR_SCHEME`) and re-resolve.
     pub fn set_scheme_override(&mut self, scheme: Option<Scheme>) {
         self.scheme_override = scheme;
         self.resolve_tokens();
     }

     /// The application scheme override, if any.
     pub fn scheme_override(&self) -> Option<Scheme> {
         self.scheme_override
     }

     /// The decoded window/surface presentation metadata.
     pub fn window(&self) -> &WindowMeta {
         &self.window
     }

     /// Clear every application design-token override (`META::RESET_THEME`) and
     /// re-resolve against the renderer defaults.
     pub fn reset_theme(&mut self) {
         self.overrides.clear();
         self.dark_overrides.clear();
         self.resolve_tokens();
     }

     /// Re-resolve every `DESIGN_TOKEN`-typed property against the theme, the
     /// active scheme, and the parent-fallback chain, materializing concrete
     /// values into [`HostNode::properties`] (numeric) or [`HostNode::strings`]
     /// (STRING tokens). The paths are kept in [`HostNode::token_refs`] for
     /// re-resolution on scheme change.
     ///
     /// Previously materialized values are removed first, so an unresolvable
     /// reference (or a reset override) leaves the property unset rather than
     /// retaining a stale value.
     pub fn resolve_tokens(&mut self) {
         let tables = TokenTables {
             overrides: &self.overrides,
             dark_overrides: &self.dark_overrides,
             defaults: &self.defaults,
             dark_defaults: &self.dark_defaults,
         };
         let scheme = self.scheme();
         for node in self.nodes.values_mut() {
             let refs: Vec<(u16, String)> =
                 node.token_refs.iter().map(|(k, v)| (*k, v.clone())).collect();
             for (prop, path) in refs {
                 node.properties.remove(&prop);
                 node.strings.remove(&prop);
                 if let Some(value) = resolve_token_ref(&path, scheme, &tables) {
                     match value {
                         TokenValue::Str(s) => {
                             node.strings.insert(prop, s);
                         }
                         _ => {
                             if let Some(bits) = value.to_bits() {
                                 node.properties.insert(prop, bits);
                             }
                         }
                     }
                 }
             }
         }
     }

     /// Apply a frame's opcodes to this tree (a delta).
     pub fn apply_frame(&mut self, frame: &Frame<'_>) {
         for op in frame.opcodes() {
             match (op.category(), op.command()) {
                 (category::TREE, tree::CREATE_NODE) => {
                     let id = op.a();
                     let ty = op.b() as u16;
                     let entry = self.nodes.entry(id).or_default();
                     entry.id = id;
                     entry.component_type = ty;
                 }
                 (category::TREE, tree::DELETE_NODE) => {
                     self.nodes.remove(&op.a());
                 }
                 (category::TREE, tree::INSERT_CHILD) => {
                     let (parent, child) = (op.a(), op.b());
                     if let Some(p) = self.nodes.get_mut(&parent) {
                         if !p.children.contains(&child) {
                             p.children.push(child);
                         }
                     }
                     if let Some(c) = self.nodes.get_mut(&child) {
                         c.parent = Some(parent);
                     }
                 }
                 (category::TREE, tree::REMOVE_CHILD) => {
                     let (parent, child) = (op.a(), op.b());
                     if let Some(p) = self.nodes.get_mut(&parent) {
                         p.children.retain(|c| *c != child);
                     }
                     if let Some(c) = self.nodes.get_mut(&child) {
                         c.parent = None;
                     }
                 }
                 (category::TREE, tree::MOVE_CHILD) => {
                     let (parent, child, new_index) = (op.a(), op.b(), op.c() as usize);
                     if let Some(p) = self.nodes.get_mut(&parent) {
                         if let Some(pos) = p.children.iter().position(|c| *c == child) {
                             p.children.remove(pos);
                         }
                         let idx = if new_index == usize::MAX {
                             p.children.len()
                         } else {
                             new_index.min(p.children.len())
                         };
                         p.children.insert(idx, child);
                     }
                 }
                 (category::PARAMETER, parameter::SET_PROPERTY) => {
                     let prop_id = op.b() as u16;
                     let vt = (op.b() >> 16) as u8;
                     if let Some(n) = self.nodes.get_mut(&op.a()) {
                         if vt == value_type::STRING {
                             // Resolve the arena offset into the actual text. A
                             // literal replaces any previous token reference.
                             n.token_refs.remove(&prop_id);
                             if let Ok(text) = frame.arena_str(op.c()) {
                                 n.strings.insert(prop_id, text.to_string());
                             }
                         } else if vt == value_type::DESIGN_TOKEN {
                             // A token reference: keep the path for resolution
                             // against the theme (spec/TOKENS.md). C is the arena
                             // offset of the token path. Drop any previously
                             // materialized literal/resolved value for this prop.
                             if let Ok(path) = frame.arena_str(op.c()) {
                                 n.properties.remove(&prop_id);
                                 n.strings.remove(&prop_id);
                                 n.token_refs.insert(prop_id, path.to_string());
                             }
                         } else if vt == value_type::LIST {
                             // An arena-backed `[u32 count][f32 × count]` array —
                             // today a VIEW_THAT_FITS `FIT_QUERY` table.
                             n.token_refs.remove(&prop_id);
                             if let Ok(bytes) = frame.arena_get(op.c()) {
                                 if let Some(values) = list_f32(bytes) {
                                     n.lists.insert(prop_id, values);
                                 }
                             }
                         } else {
                             n.token_refs.remove(&prop_id);
                             n.properties.insert(prop_id, op.c());
                         }
                     }
                 }
                 (category::PARAMETER, parameter::SET_TEXT) => {
                     if let Some(n) = self.nodes.get_mut(&op.a()) {
                         n.text = frame.arena_str(op.b()).ok().map(|s| s.to_string());
                         n.attributed = None;
                     }
                 }
                 (category::PARAMETER, parameter::SET_ATTRIBUTED_TEXT) => {
                     if let Some(n) = self.nodes.get_mut(&op.a()) {
                         if let Ok(bytes) = frame.arena_get(op.b()) {
                             if let Ok(value) = AttributedString::decode(bytes) {
                                 n.text = Some(value.text().to_string());
                                 n.attributed = Some(value);
                             }
                         }
                     }
                 }
                 (category::PARAMETER, parameter::SET_DATE) => {
                     // A = node, B = days since epoch (I32), C = millis of day.
                     if let Some(n) = self.nodes.get_mut(&op.a()) {
                         n.date = Some((op.b() as i32, op.c()));
                     }
                 }
                 (category::PARAMETER, parameter::SET_DESIGN_TOKEN) => {
                     // Global override: A = arenaRef (token path), B = valueType,
                     // C = value (for STRING, an arenaRef to the value string).
                     if let Ok(path) = frame.arena_str(op.a()) {
                         let vt = (op.b() & 0xFF) as u8;
                         let value = if vt == value_type::STRING {
                             frame
                                 .arena_str(op.c())
                                 .map(|s| TokenValue::Str(s.to_string()))
                                 .unwrap_or(TokenValue::U32(0))
                         } else {
                             TokenValue::from_wire(vt, op.c()).unwrap_or(TokenValue::U32(op.c()))
                         };
                         if let Some(bare) = path.strip_prefix("dark.") {
                             self.dark_overrides.insert(bare.to_string(), value);
                         } else {
                             self.overrides.insert(path.to_string(), value);
                         }
                     }
                 }
                 (category::META, meta::SET_COLOR_SCHEME) => {
                     self.scheme_override = match op.a() {
                         color_scheme_mode::LIGHT => Some(Scheme::Light),
                         color_scheme_mode::DARK => Some(Scheme::Dark),
                         _ => None,
                     };
                 }
                 (category::META, meta::RESET_THEME) => {
                     self.overrides.clear();
                     self.dark_overrides.clear();
                 }
                 (category::META, meta::SET_WINDOW_METADATA) => {
                     // Empty string clears the field (spec/OPCODE.md §Window metadata).
                     if let Ok(value) = frame.arena_str(op.b()) {
                         self.window.set(op.a() as u16, value);
                     }
                 }
                 _ => {}
             }
         }
         self.resolve_tokens();
     }

     /// Look up a node by id.
     pub fn node(&self, id: u32) -> Option<&HostNode> {
         self.nodes.get(&id)
     }

     /// The root node: the single node without a parent.
     pub fn root(&self) -> Option<&HostNode> {
         self.nodes.values().find(|n| n.parent.is_none())
     }
 }

 /// Read a length-prefixed f32 array (`[u32 count][f32 × count]`) from an arena
 /// entry — the numeric form of a `LIST`-typed value (spec/OPCODE.md).
 fn list_f32(entry: &[u8]) -> Option<Vec<f32>> {
     if entry.len() < 4 {
         return None;
     }
     let count = u32::from_le_bytes(entry[..4].try_into().ok()?) as usize;
     let start = 4;
     if start + count * 4 > entry.len() {
         return None;
     }
     let mut values = Vec::with_capacity(count);
     for i in 0..count {
         let bits = u32::from_le_bytes(entry[start + i * 4..start + i * 4 + 4].try_into().ok()?);
         values.push(f32::from_bits(bits));
     }
     Some(values)
 }

 /// Decode a frame into a fresh `RenderTree`.
 pub fn render_tree_from_frame(frame: &Frame<'_>) -> RenderTree {
     let mut tree = RenderTree::default();
     tree.apply_frame(frame);
     tree
 }

