     fn apply(&self, node: &mut Node) {
         apply_length(node, property_id::PADDING, &self.value);
     }
 }

 impl ViewModifier for FontSize {
     fn apply(&self, node: &mut Node) {
         apply_length(node, property_id::FONT_SIZE, &self.value);
