         for (child, expected) in node.children.iter().zip(extents.iter()) {
             assert_eq!(
                 child
                     .properties
                     .get(&property_id::HEIGHT)
                     .copied()
                     .map(f32::from_bits),
                 Some(*expected)
             );
         }
     }

