 /// Cross-axis alignment values for stacks and the `Frame` compound modifier.
 ///
 /// These are emitted as the `ALIGNMENT` (0x0002) property with an `ENUM` value
 /// type (low byte of the property value). Alignment is **position-only**
 /// (codes 0–2; the protocol's 2D codes 3–8 are the other positions, see
 /// spec/PRIMITIVES.md §ZStack): stretching is a child's `FILL` size, never an
 /// alignment.
 #[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
 pub enum Align {
     /// Align to the leading (start) edge.
     #[default]
     Leading,
     /// Center along the cross axis.
     Center,
     /// Align to the trailing (end) edge.
     Trailing,
 }

 impl Align {
     /// The protocol enum value for this alignment.
     pub fn value(self) -> u8 {
         match self {
             Align::Leading => 0,
             Align::Center => 1,
             Align::Trailing => 2,
         }
     }
 }

 /// Shape geometry for a `SHAPE` node (the `SHAPE_KIND` enum).
 #[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
 pub enum ShapeKind {
     Circle = 0,
     #[default]
     Rectangle = 1,
     RoundedRectangle = 2,
     Capsule = 3,
     Ellipse = 4,
     Path = 5,
 }

 impl ShapeKind {
     /// The protocol enum value for this shape.
     pub fn value(self) -> u8 {
         self as u8
     }
 }

 /// A `SCROLLVIEW`'s scroll axis (the `SCROLL_AXIS` enum, spec/PRIMITIVES.md
 /// §ScrollView). The view is layout-greedy on this axis; the cross axis hugs its
 /// content (a `Fill`-sized content child propagates `Fill`).
 #[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
 pub enum ScrollAxis {
     /// Scroll vertically (the default).
     #[default]
     Vertical,
     /// Scroll horizontally.
     Horizontal,
 }

 impl ScrollAxis {
     /// The protocol enum value for this axis.
     pub fn value(self) -> u8 {
         match self {
             ScrollAxis::Vertical => 0,
             ScrollAxis::Horizontal => 1,
         }
     }
 }

 // ---------------------------------------------------------------------------
 // Modifiers
 // ---------------------------------------------------------------------------

 /// A config value that is either a **static** value or a **signal binding**
 /// (spec DSL.md §2): a static value emits as a plain property; a signal becomes a
 /// node-level binding that re-emits only that property when it changes. This is
 /// the Rust realization of "every value member accepts a raw value or a signal".
 #[derive(Debug, Clone, Copy, PartialEq)]
 pub enum Reactive<T> {
     /// A raw, non-reactive value.
     Static(T),
     /// A property bound to a signal.
     Signal(SignalId),
 }

 /// Convert a raw value or a signal into a [`Reactive`] config value. Implemented
 /// for `T` (static) and for `Signal<T>`/`WritableSignal<T>` (binding); the former
 /// `Bound` modifier folds into this.
 pub trait IntoReactive<T> {
     /// Convert into a [`Reactive`].
     fn into_reactive(self) -> Reactive<T>;
 }

 impl<T> IntoReactive<T> for T {
     fn into_reactive(self) -> Reactive<T> {
         Reactive::Static(self)
     }
 }

 impl<T> IntoReactive<T> for Signal<T> {
     fn into_reactive(self) -> Reactive<T> {
         Reactive::Signal(self.id())
     }
 }

 impl<T> IntoReactive<T> for WritableSignal<T> {
     fn into_reactive(self) -> Reactive<T> {
         Reactive::Signal(self.id())
     }
 }

 /// Apply a reactive f32 property (static value or signal binding).
 fn reactive_f32(node: &mut Node, prop: u16, r: &Reactive<f32>) {
     match r {
         Reactive::Static(v) => {
             node.properties.insert(prop, v.to_bits());
         }
         Reactive::Signal(id) => {
             node.property_bindings.insert(prop, *id);
         }
     }
 }

 /// A length value: a literal dp/point value or a **design-token reference**
 /// (spec/TOKENS.md). A token reference emits the `DESIGN_TOKEN` value type in an
 /// F32-typed property and is resolved by the renderer.
 #[derive(Debug, Clone, Copy, PartialEq)]
 pub enum Length {
     /// A literal value in device pixels/points.
     Literal(f32),
     /// A design-token path (e.g. `space.2`, `font.body.size`).
     Token(&'static str),
 }

 impl Length {
     /// A design-token reference.
     pub const fn token(path: &'static str) -> Self {
         Length::Token(path)
     }

     /// A literal length.
     pub const fn of(value: f32) -> Self {
         Length::Literal(value)
     }
 }

 /// A static, signal-bound, or token length used by a modifier config.
 #[derive(Debug, Clone, Copy, PartialEq)]
 pub enum LengthValue {
     /// A static value or signal binding.
     Reactive(Reactive<f32>),
     /// A design-token reference.
     Token(&'static str),
 }

 /// Convert a raw/signal length or a [`Length`] token into a [`LengthValue`].
 pub trait IntoLength {
     /// Convert into a [`LengthValue`].
     fn into_length(self) -> LengthValue;
 }

 impl IntoLength for f32 {
     fn into_length(self) -> LengthValue {
         LengthValue::Reactive(Reactive::Static(self))
     }
 }

 impl IntoLength for Reactive<f32> {
     fn into_length(self) -> LengthValue {
         LengthValue::Reactive(self)
     }
 }

 impl IntoLength for Signal<f32> {
     fn into_length(self) -> LengthValue {
         LengthValue::Reactive(Reactive::Signal(self.id()))
     }
 }

 impl IntoLength for WritableSignal<f32> {
     fn into_length(self) -> LengthValue {
         LengthValue::Reactive(Reactive::Signal(self.id()))
     }
 }

 impl IntoLength for Length {
     fn into_length(self) -> LengthValue {
         match self {
             Length::Literal(v) => LengthValue::Reactive(Reactive::Static(v)),
             Length::Token(path) => LengthValue::Token(path),
         }
     }
 }

 /// Apply a length property: a literal/signal behaves like [`reactive_f32`]; a
 /// token reference rides `Node::token_properties` as `DESIGN_TOKEN`.
 fn apply_length(node: &mut Node, prop: u16, value: &LengthValue) {
     match value {
         LengthValue::Reactive(r) => reactive_f32(node, prop, r),
         LengthValue::Token(path) => {
             node.properties.remove(&prop);
             node.token_properties.insert(prop, String::from(*path));
         }
     }
 }

 /// Apply a reactive enum property (a `u8` code stored as `F32`).
 fn reactive_enum(node: &mut Node, prop: u16, r: &Reactive<u8>) {
     match r {
         Reactive::Static(v) => {
             node.properties.insert(prop, (*v as f32).to_bits());
         }
         Reactive::Signal(id) => {
             node.property_bindings.insert(prop, *id);
         }
     }
 }

 /// Apply a reactive u32 property.
 fn reactive_u32(node: &mut Node, prop: u16, r: &Reactive<u32>) {
     match r {
         Reactive::Static(v) => {
             node.properties.insert(prop, *v);
         }
         Reactive::Signal(id) => {
             node.property_bindings.insert(prop, *id);
         }
     }
 }

 /// Apply a reactive color property (literal/token static, or signal binding).
 fn reactive_color(node: &mut Node, prop: u16, r: &Reactive<Color>) {
     match r {
         Reactive::Static(c) => apply_color(node, prop, *c),
         Reactive::Signal(id) => {
             node.property_bindings.insert(prop, *id);
         }
     }
 }

 /// Uniform padding (a styling modifier, applied to any view). `Padding(16.0)` is
 /// static; `Padding(signal)` binds `PADDING` to a signal.
 #[derive(Debug, Clone, Copy, PartialEq)]
 pub struct Padding {
     value: LengthValue,
 }

 /// A uniform padding value (raw, signal, or token).
 #[allow(non_snake_case)]
 pub fn Padding(value: impl IntoLength) -> Padding {
     Padding {
         value: value.into_length(),
     }
 }

 /// Text font size in points. `FontSize(28.0)` static, `FontSize(signal)` bound.
 #[derive(Debug, Clone, Copy, PartialEq)]
 pub struct FontSize {
     value: LengthValue,
 }

 /// A font size value (raw, signal, or token).
 #[allow(non_snake_case)]
 pub fn FontSize(value: impl IntoLength) -> FontSize {
     FontSize {
         value: value.into_length(),
