 }

 impl VideoConfig {
     /// Set the controller this surface renders.
     pub fn controller(&mut self, controller: Rc<MediaController>) -> &mut Self {
         self.controller = Some(controller);
         self
     }
 }

 impl Video {
     /// A video surface rendering `controller`'s output.
