+    }
+}
+
+/// An inset list: full-width rows with inset separators and no grouped card.
+pub struct InsetListStyle;
+
+impl ListStyle for InsetListStyle {
+    fn row_extent_overhead(&self) -> f32 {
+        LIST_ROW_OVERHEAD
+    }

