package dev.pathland.demo.music

import dev.pathland.demo.music.player.PlayerMainArea
import dev.pathland.demo.music.service.MediaPlayerService
import dev.pathland.demo.music.sidebar.NowPlayingSidebar
import dev.pathland.view.core.Color
import dev.pathland.view.core.Roles
import dev.pathland.view.core.View
import dev.pathland.core.protocol.Commands
import dev.pathland.view.dsl.Component
import dev.pathland.view.dsl.Fit
import dev.pathland.view.dsl.HStack
import dev.pathland.view.dsl.VStack
import dev.pathland.view.dsl.ViewThatFits
import dev.pathland.view.dsl.accessibilityRole
import dev.pathland.view.dsl.clipped
import dev.pathland.view.dsl.computed
import dev.pathland.view.dsl.environment
import dev.pathland.view.dsl.frame
import dev.pathland.view.dsl.windowMetadata

/**
 * The music player demo root view — an Apple Music-style player authored purely
 * with the Kotlin DSL, composed of the [PlayerMainArea] (library + floating
 * player bar) and the wide-layout [NowPlayingSidebar].
 *
 * The root owns the per-session [MediaPlayerService] and scopes it through the
 * environment; child views resolve the service instead of receiving its signals
 * through their constructors.
 */
class MusicPlayerView @JvmOverloads constructor(
    private val adUrl: String? = null,
) : Component() {

    companion object {
        const val SIDEBAR_WIDTH = 280f
        const val BAR_HEIGHT = 76f

        // Gray-600: >= 4.5:1 on white, the sidebar, the selected row, and the player bar.
        val SECONDARY_FG: Color = Color.rgb(0x4B, 0x55, 0x63)
        val ACTIVE_ROW_BG: Color = Color.rgb(0xE8, 0xEF, 0xFF)
        val INACTIVE_ROW_BG: Color = Color.rgb(0xE5, 0xE5, 0xEA)
        val ACTIVE_ROW_FG: Color = Color.rgb(0x1A, 0x3A, 0x8C)
        val SIDEBAR_BG: Color = Color.rgb(0xF6, 0xF7, 0xFA)
        val BAR_BORDER: Color = Color.rgb(0xFF, 0xFF, 0xFF)
        val BAR_BG: Color = Color.argb(0xBF, 0xEB, 0xEB, 0xED)

        /** A player with no sponsored slot (Java-compatible factory). */
        @JvmStatic
        fun make(): MusicPlayerView = MusicPlayerView()

        /** A player with a sponsored slot proxying [adUrl] (Java-compatible factory). */
        @JvmStatic
        fun make(adUrl: String?): MusicPlayerView = MusicPlayerView(adUrl)
    }

    private val service by lazy { MediaPlayerService() }

    override fun body(): View {
        val mediaPlayer = service

        // One root fit slot selects the complete layout for the window width:
        // narrow (no volume, compact transport), medium (volume), wide (volume +
        // now-playing sidebar). Keeping the breakpoint at the root avoids a
        // nested fit slot whose wide-only children could survive a candidate swap.
        val narrowRow = HStack {
            PlayerMainArea(wide = false)
        }.frame(width = Commands.Size.FILL, height = Commands.Size.FILL)

        val mediumRow = HStack {
            PlayerMainArea(wide = true)
        }.frame(width = Commands.Size.FILL, height = Commands.Size.FILL)

        val wideRow = HStack {
            PlayerMainArea(wide = true)
            NowPlayingSidebar(adUrl).clipped()
        }.frame(width = Commands.Size.FILL, height = Commands.Size.FILL)

        return VStack {
            ViewThatFits(
                Fit(narrowRow),
                Fit(mediumRow, 700f),
                Fit(wideRow, 1024f),
            ).frame(width = Commands.Size.FILL, height = Commands.Size.FILL)
                .accessibilityRole(Roles.MAIN)
        }.frame(width = Commands.Size.FILL, height = Commands.Size.FILL)
            .environment(MediaPlayerService.KEY, mediaPlayer)
            .windowMetadata {
                title(computed { "Pathland · " + mediaPlayer.currentTrack.get().title })
                description(computed {
                    mediaPlayer.currentTrack.get().artist + " · " + mediaPlayer.currentTrack.get().album
                })
                locale("en")
            }
    }
}

package dev.pathland.demo.music.library

import dev.pathland.demo.music.MusicPlayerView
import dev.pathland.demo.music.service.mediaPlayerService
import dev.pathland.view.core.Color
import dev.pathland.view.core.FontWeight
import dev.pathland.view.core.HorizontalAlignment
import dev.pathland.view.core.Keys
import dev.pathland.view.core.Roles
import dev.pathland.view.core.VerticalAlignment
import dev.pathland.view.core.View
import dev.pathland.view.core.subscription.SessionContext
import dev.pathland.core.protocol.Commands
import dev.pathland.view.dsl.Divider
import dev.pathland.view.dsl.ForEach
import dev.pathland.view.dsl.Font
import dev.pathland.view.dsl.Component
import dev.pathland.view.dsl.HStack
import dev.pathland.view.dsl.LazySelection
import dev.pathland.view.dsl.LazyVStack
import dev.pathland.view.dsl.ScrollView
import dev.pathland.view.dsl.Spacer
import dev.pathland.view.dsl.Text
import dev.pathland.view.dsl.VStack
import dev.pathland.view.dsl.accessibilityRole
import dev.pathland.view.dsl.font
import dev.pathland.view.dsl.fontSize
import dev.pathland.view.dsl.fontWeight
import dev.pathland.view.dsl.foregroundStyle
import dev.pathland.view.dsl.frame
import dev.pathland.view.dsl.padding

/** The fixed main-axis height of a library row (the lazy window's extent). */
internal const val LIBRARY_ROW_HEIGHT = 64f

/** A subtle placeholder tone for a not-yet-loaded row. */
private val SKELETON = Color.argb(0x26, 0x4B, 0x55, 0x63)

/** A placeholder row shown while a page is loading. */
private fun TrackRowSkeleton(): View = HStack(
    alignment = VerticalAlignment.CENTER,
    spacing = 12f,
) {
    SKELETON.frame(width = 44f, height = 44f)
    VStack(alignment = HorizontalAlignment.LEADING, spacing = 6f) {
        SKELETON.frame(width = 160f, height = 10f)
        SKELETON.frame(width = 110f, height = 8f)
    }
    Spacer()
    SKELETON.frame(width = 34f, height = 8f)
}.padding(6f).frame(height = LIBRARY_ROW_HEIGHT)

/**
 * The library pane: the "Library" header and the full track list. Each row is a
 * [TrackRowView]; selecting one starts that track through the shared player
 * service. The list is a windowed `LazyVStack` over the repeated library.
 */
internal class LibraryView : Component() {

    override fun body(): View {
        val service = mediaPlayerService()
        // A live/SSR session uses the paged source; an emitter-only unit-test
        // mount (no session context) keeps the in-memory list.
        val source = SessionContext.current()?.let { service.librarySource }

        return VStack {
            Text("Library")
                .font(Font.largeTitle())
                .fontSize(26f)
                .fontWeight(FontWeight.BOLD)
                .accessibilityRole(Roles.HEADER)

            Text("${service.tracks.size} songs · ${service.tracks.size} albums")
                .foregroundStyle(MusicPlayerView.SECONDARY_FG)

            Divider().padding(top = 0f, right = 0f, bottom = 10f, left = 0f)

            ScrollView {
                if (source != null && source.loading.get() && source.total.get() == 0) {
                    Text("Loading library…")
                        .foregroundStyle(MusicPlayerView.SECONDARY_FG)
                } else {
                    LazyVStack(
                        spacing = 0f,
                        selection = LazySelection(
                            selectedIndex = service.focusedIndex,
                            focusState = service.listFocused,
                            onActivate = service::selectTrack,
                            onTap = service::selectTrack,
                            onKeyDown = { _, key ->
                                if (key.keyCode == Keys.SPACE) {
                                    service.togglePlay()
                                    true
                                } else {
                                    false
                                }
                            },
                        ),
                    ) {
                        if (source != null) {
                            ForEach(
                                source,
                                itemExtent = LIBRARY_ROW_HEIGHT,
                                placeholder = {
                                    TrackRowSkeleton().frame(height = LIBRARY_ROW_HEIGHT)
                                },
                            ) { track, index ->
                                TrackRowView(track, index).frame(height = LIBRARY_ROW_HEIGHT)
                            }
                        } else {
                            ForEach(service.tracks) { track, index ->
                                TrackRowView(track, index).frame(height = LIBRARY_ROW_HEIGHT)
                            }
                        }
                    }
                }
            }
        }.padding(24f)
            .frame(width = Commands.Size.FILL, height = Commands.Size.FILL)
    }
}

package dev.pathland.demo.music.service

import dev.pathland.demo.music.model.Track
import dev.pathland.view.core.Environment
import dev.pathland.view.core.EnvironmentKey
import dev.pathland.view.core.MediaController
import dev.pathland.view.core.signal.Signal
import dev.pathland.view.core.signal.Signals
import dev.pathland.view.core.signal.WritableSignal
import dev.pathland.view.data.Page
import dev.pathland.view.data.PagedDataSource

/**
 * The demo's app-owned media-player service. It owns the playlist/track state,
 * the six persisted player signals, and the [MediaController] transport. Views
 * resolve it from the environment through [MediaPlayerService.KEY].
 *
 * The service is created once per root/session; it must never be a global
 * singleton (signals are single-threaded and per-session).
 */
internal class MediaPlayerService {

    val trackIndex: WritableSignal<Int> = Signals.state("player.track", 0)
    val playing: WritableSignal<Boolean> = Signals.state("player.playing", false)
    val position: WritableSignal<Float> = Signals.state("player.position", 0f)
    val volume: WritableSignal<Float> = Signals.state("player.volume", 0.7f)
    val seekRequest: WritableSignal<Float> = Signals.state("player.seekRequest", 0f)
    val volumeRequest: WritableSignal<Float> = Signals.state("player.volumeRequest", 0.7f)

    /**
     * Ephemeral keyboard focus in the library (not persisted): the roving tab
     * stop and lazy-window pin. Kept on the shared service so it survives the
     * root `ViewThatFits` candidate swaps.
     */
    val focusedIndex: WritableSignal<Int> = Signals.signal(0)
    val listFocused: WritableSignal<Boolean> = Signals.signal(false)

    val controller = MediaController()
    /** The demo library: the base tracks repeated to [LIBRARY_SIZE] entries. */
    val tracks: List<Track> = List(LIBRARY_SIZE) { TRACKS[it % TRACKS.size] }
    val currentTrack: Signal<Track> = Signals.computed { at(trackIndex.get()) }

    /**
     * The paged library source used by the live/SSR session. Unit-test mounts
     * (no session context) keep the in-memory [tracks] list instead.
     */
    val librarySource: PagedDataSource<Track> by lazy {
        PagedDataSource.ofBlocking(LIBRARY_PAGE_SIZE, { offset, limit -> page(offset, limit) })
    }

    init {
        controller.register()
        controller.source(Signals.computed { currentTrack.get().audio })
        controller.playing(playing)
        controller.position(seekRequest)
        controller.volume(volumeRequest)
        controller.time(position)
        controller.volumeReport(volume)
        controller.onEnded { ended() }
    }


    /** Select a track and start it from the top. */
    fun selectTrack(index: Int) {
        trackIndex.set(index)
        position.set(0f)
        seekRequest.set(0f)
        playing.set(true)
    }

    /** Previous track (wraps around), restarting from the top. */
    fun previous() {
        trackIndex.set((trackIndex.get() - 1 + tracks.size) % tracks.size)
        controller.seek(0f)
    }

    /** Next track (wraps around), restarting from the top. */
    fun next() {
        trackIndex.set((trackIndex.get() + 1) % tracks.size)
        controller.seek(0f)
    }

    fun togglePlay() {
        controller.toggle()
    }

    /**
     * One page of the in-memory library (the demo's "database"). A small delay
     * makes the loading/placeholder path visible in the browser.
     */
    fun page(offset: Int, limit: Int): Page<Track> {
        if (PAGE_DELAY_MILLIS > 0) {
            try {
                Thread.sleep(PAGE_DELAY_MILLIS)
            } catch (interrupted: InterruptedException) {
                Thread.currentThread().interrupt()
            }
        }
        val start = offset.coerceIn(0, tracks.size)
        val end = (offset + limit).coerceIn(start, tracks.size)
        val items = if (start == end) emptyList() else tracks.subList(start, end)
        return Page(items, total = tracks.size, hasMore = end < tracks.size)
    }

    /** The track at an index (wraps around; safe for any signed index). */
    private fun at(index: Int): Track = tracks[Math.floorMod(index, tracks.size)]

    /** The track [offset] places after the current one (wraps around). */
    fun trackAt(offset: Int): Track = at(trackIndex.get() + offset)

    private fun ended() {
        trackIndex.set((trackIndex.get() + 1) % tracks.size)
        seekRequest.set(0f)
        position.set(0f)
    }

    companion object {
        /** The number of repeated library entries (the demo's long list). */
        const val LIBRARY_SIZE = 1000

        /** The paged library page size (rows loaded per page). */
        const val LIBRARY_PAGE_SIZE = 50

        /** A small simulated data-source latency for the demo's loading state. */
        private const val PAGE_DELAY_MILLIS = 40L

        /** The environment key for the active [MediaPlayerService]. */
        val KEY: EnvironmentKey<MediaPlayerService> =
            EnvironmentKey.of("mediaPlayerService")

        /** The demo library: eight Pathland concept tracks, one album each. */
        internal val TRACKS: List<Track> = listOf(
            Track(
                "Building on Solid Ground", "The Foundation", "The Open Horizon", 178f,
                "/_pathland/assets/albumart/cover1.jpg",
                "/_pathland/assets/albumart/thumbs/cover1.jpg",
                "/_pathland/assets/audio/track1.mp3",
            ),
            Track(
                "Pathland Crossing", "The Crossings", "Native Operations", 166f,
                "/_pathland/assets/albumart/cover2.jpg",
                "/_pathland/assets/albumart/thumbs/cover2.jpg",
                "/_pathland/assets/audio/track2.mp3",
            ),
            Track(
                "Rendered Free", "Rena Render", "Grace From The Source", 182f,
                "/_pathland/assets/albumart/cover3.jpg",
                "/_pathland/assets/albumart/thumbs/cover3.jpg",
                "/_pathland/assets/audio/track3.mp3",
            ),
            Track(
                "Rendered In Your Arms", "Ember Frame", "Architectures of Grace", 160f,
                "/_pathland/assets/albumart/cover4.jpg",
                "/_pathland/assets/albumart/thumbs/cover4.jpg",
                "/_pathland/assets/audio/track4.mp3",
            ),
