                 (it.b() and 0xFFFF) == property &&
                 java.lang.Float.intBitsToFloat(it.c()) == value
         }

     private fun propertyFloat(frame: ProtocolFrame, nodeId: Int, property: Int): Float {
         for (op: Opcode in frame.opcodes()) {
             if (op.category() == Categories.PARAMETER &&
                 op.command() == Commands.Parameter.SET_PROPERTY &&
                 op.a() == nodeId &&
                 (op.b() and 0xFFFF) == property
             ) {
                 return java.lang.Float.intBitsToFloat(op.c())
             }
         }
         return Float.NaN
     }

     private fun seekSliderId(frame: ProtocolFrame): Int =
         sliderIdByMax(frame, 100f, "seek")

     private fun volumeSliderId(frame: ProtocolFrame): Int =
         sliderIdByMax(frame, 1f, "volume")

     private fun sliderIdByMax(frame: ProtocolFrame, max: Float, label: String): Int {
         for (op: Opcode in frame.opcodes()) {
             if (op.category() == Categories.PARAMETER &&
                 op.command() == Commands.Parameter.SET_PROPERTY &&
                 (op.b() and 0xFFFF) == Properties.MAX_VALUE &&
                 java.lang.Float.intBitsToFloat(op.c()) == max
             ) {
                 return op.a()
             }
         }
         throw AssertionError("the $label slider is not in the frame")
     }

     private fun fitThresholds(frame: ProtocolFrame, slotId: Int): FloatArray {
         for (op: Opcode in frame.opcodes()) {
             if (op.category() == Categories.PARAMETER &&
                 op.command() == Commands.Parameter.SET_PROPERTY &&
                 op.a() == slotId &&
                 (op.b() and 0xFFFF) == Properties.FIT_QUERY
             ) {
                 val strings = frame.strings()
                 val offset = op.c()
                 val count = le32(strings, offset)
                 return FloatArray(count) {
                     java.lang.Float.intBitsToFloat(le32(strings, offset + 4 + it * 4))
                 }
             }
         }
         throw AssertionError("no FIT_QUERY for slot $slotId")
     }

     private fun slotIdByMaxThreshold(frame: ProtocolFrame, maxThreshold: Float): Int {
         for (op: Opcode in frame.opcodes()) {
             if (op.category() == Categories.TREE &&
                 op.command() == Commands.Tree.CREATE_NODE &&
                 op.b() == Components.VIEW_THAT_FITS
             ) {
                 val thresholds = fitThresholds(frame, op.a())
                 if (thresholds.last() == maxThreshold) return op.a()
             }
         }
         throw AssertionError("no fit slot with max threshold $maxThreshold")
     }

     private fun le32(bytes: ByteArray, offset: Int): Int =
         (bytes[offset].toInt() and 0xFF) or
             ((bytes[offset + 1].toInt() and 0xFF) shl 8) or
             ((bytes[offset + 2].toInt() and 0xFF) shl 16) or
             ((bytes[offset + 3].toInt() and 0xFF) shl 24)

     private companion object {
         const val COVER = "/_pathland/assets/albumart/thumbs/cover1.jpg"
     }

     @Test
     fun keyboardArrowsMoveRovingFocusAndEnterPlays() {
         val mounted = mount()
         val frame = mounted.sink.frame()
         val focused = frame.opcodes().filter {
             it.category() == Categories.PARAMETER &&
                 it.command() == Commands.Parameter.SET_PROPERTY &&
                 (it.b() and 0xffff) == Properties.EVENT_LISTENERS &&
                 (it.c() and Commands.Listeners.FOCUS) != 0
         }.map { it.a() }
         assertEquals(1, focused.size, "exactly one roving tab stop")

         val dispatcher = InputDispatcher(mounted.result, Signals.signal("/"))
         dispatcher.dispatch(Event.keyDown(focused.single(), Keys.ARROW_DOWN, 0, 0))

         val moved = mounted.sink.frame()
         val focusOp = moved.opcodes().single {
             it.category() == Categories.META && it.command() == Commands.Meta.SET_FOCUS &&
                 it.b() != 0
         }
         assertTrue(focusOp.a() != focused.single(), "focus moved to the next row")
         assertEquals(1, focusOp.b())

         dispatcher.dispatch(Event.keyDown(focusOp.a(), Keys.ENTER, 0, 0))
         assertEquals(
             1,
             mounted.store.load("player.track:session-1", Integer::class.java).get(),
             "Enter plays the focused row",
         )

         dispatcher.dispatch(Event.keyDown(focusOp.a(), Keys.END, 0, 0))
         val end = mounted.sink.frame().opcodes().single {
             it.category() == Categories.META && it.command() == Commands.Meta.SET_FOCUS &&
                 it.b() != 0
         }
         assertTrue(end.a() != focusOp.a(), "End moves focus to the last row")

         dispatcher.dispatch(Event.keyDown(end.a(), Keys.HOME, 0, 0))
         val home = mounted.sink.frame().opcodes().single {
             it.category() == Categories.META && it.command() == Commands.Meta.SET_FOCUS &&
                 it.b() != 0
         }
         assertTrue(home.a() != end.a(), "Home moves focus away from the last row")
     }
 }

